          body: "가사소송법 제22조는 재판상 이혼의 소를 부부의 주소지 등을 기준으로 정해진 가정법원의 전속관할로 한다고 정해요. 배우자가 교도소에 있어도 관할은 수용 시설의 위치가 아니라 부부의 주소지 등을 기준으로 정해져요. 소가 제기되면 가사소송법 제12조에 따라 민사소송법이 준용되는 절차로 송달과 심리가 진행돼요. 다만 가사소송법 제12조 단서에 따라 이혼 소송과 같은 나류 가사소송사건에는 민사소송법의 자백 간주와 청구의 인낙에 관한 규정이 적용되지 않아, 상대방이 송달을 받고도 응답하지 않더라도 자백한 것으로 보지 않고 원고가 이혼 사유가 있다는 사실을 증명해야 해요.",
